#include <bits/stdc++.h>
using namespace std;

static string in;
static size_t pos_ = 0;

static void appendUtf8(string &s, unsigned cp) {
    // Lone surrogates are kept as 3-byte sequences so distinct names stay distinct.
    if (cp < 0x80) s += (char)cp;
    else if (cp < 0x800) { s += (char)(0xC0 | (cp >> 6)); s += (char)(0x80 | (cp & 0x3F)); }
    else if (cp < 0x10000) {
        s += (char)(0xE0 | (cp >> 12)); s += (char)(0x80 | ((cp >> 6) & 0x3F)); s += (char)(0x80 | (cp & 0x3F));
    } else {
        s += (char)(0xF0 | (cp >> 18)); s += (char)(0x80 | ((cp >> 12) & 0x3F));
        s += (char)(0x80 | ((cp >> 6) & 0x3F)); s += (char)(0x80 | (cp & 0x3F));
    }
}

static unsigned hex4(size_t at) {
    unsigned v = 0;
    for (size_t i = at; i < at + 4; i++) {
        char c = in[i];
        v = v * 16 + (c <= '9' ? c - '0' : (c | 32) - 'a' + 10);
    }
    return v;
}

// Parses the JSON string starting at the opening quote.
static string parseString() {
    string s;
    pos_++;
    while (in[pos_] != '"') {
        char c = in[pos_++];
        if (c != '\\') { s += c; continue; }
        char e = in[pos_++];
        switch (e) {
            case 'n': s += '\n'; break;
            case 't': s += '\t'; break;
            case 'r': s += '\r'; break;
            case 'b': s += '\b'; break;
            case 'f': s += '\f'; break;
            case 'u': {
                unsigned cp = hex4(pos_);
                pos_ += 4;
                if (cp >= 0xD800 && cp < 0xDC00 && in[pos_] == '\\' && in[pos_ + 1] == 'u') {
                    unsigned lo = hex4(pos_ + 2);
                    if (lo >= 0xDC00 && lo < 0xE000) {
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        pos_ += 6;
                    }
                }
                appendUtf8(s, cp);
                break;
            }
            default: s += e;  // \" \\ \/
        }
    }
    pos_++;
    return s;
}

static bool isWs(char c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f'; }

int main() {
    char chunk[1 << 16];
    size_t got;
    while ((got = fread(chunk, 1, sizeof chunk, stdin)) > 0) in.append(chunk, got);
    unordered_map<string, long long> holdings;
