            size_t j = i;
            while (j < line.size() && !isWs(line[j])) j++;
            if (j > i) p.emplace_back(line, i, j - i);
            i = j;
        }
        if (p[0] == "QUERY") { out.push_back(gain); continue; }
        long long v = stoll(p[2]);
        if (p[0] == "CHANGE") {
            auto it = holdings.find(p[1]);
            if (it != holdings.end()) gain += it->second * v;
