import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static String in;
    static int pos = 0;

    // Parses the JSON string starting at the opening quote.
    static String parseString() {
        StringBuilder s = new StringBuilder();
        pos++;
        while (in.charAt(pos) != '"') {
            char c = in.charAt(pos++);
            if (c != '\\') { s.append(c); continue; }
            char e = in.charAt(pos++);
            switch (e) {
                case 'n': s.append('\n'); break;
                case 't': s.append('\t'); break;
                case 'r': s.append('\r'); break;
                case 'b': s.append('\b'); break;
                case 'f': s.append('\f'); break;
                case 'u': s.append((char) Integer.parseInt(in.substring(pos, pos + 4), 16)); pos += 4; break;
                default: s.append(e);  // \" \\ \/
            }
        }
        pos++;
        return s.toString();
    }

    static boolean isWs(char c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == 0x0B || c == '\f'; }

    public static void main(String[] args) throws IOException {
        in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        HashMap<String, Long> holdings = new HashMap<>();
        long gain = 0;
        StringBuilder out = new StringBuilder();
        int queries = 0;
        while (pos < in.length() && in.charAt(pos) != '[') pos++;
        pos++;
        List<String> p = new ArrayList<>();
        while (true) {
            while (pos < in.length() && in.charAt(pos) != '"' && in.charAt(pos) != ']') pos++;
            if (pos >= in.length() || in.charAt(pos) == ']') break;
            String line = parseString();
            p.clear();
            int i = 0;
            while (i < line.length()) {
                while (i < line.length() && isWs(line.charAt(i))) i++;
                int j = i;
                while (j < line.length() && !isWs(line.charAt(j))) j++;
                if (j > i) p.add(line.substring(i, j));
                i = j;
            }
            String op = p.get(0);
            if (op.equals("QUERY")) { queries++; out.append(gain).append('\n'); continue; }
            long v = Long.parseLong(p.get(2));
            if (op.equals("CHANGE")) gain += holdings.getOrDefault(p.get(1), 0L) * v;
            else holdings.merge(p.get(1), op.equals("BUY") ? v : -v, Long::sum);
        }
        System.out.print(queries + "\n" + out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"unicode/utf8"
)

var in []byte
var pos int

func hex4(at int) rune {
	var v rune
	for _, c := range in[at : at+4] {
		switch {
		case c <= '9':
			v = v*16 + rune(c-'0')
		default:
			v = v*16 + rune(c|32-'a') + 10
		}
	}
	return v
}

// appendCode writes a code point as UTF-8; lone surrogates keep a 3-byte form so names stay distinct.
func appendCode(s []byte, cp rune) []byte {
	if cp >= 0xD800 && cp < 0xE000 {
		return append(s, byte(0xE0|cp>>12), byte(0x80|(cp>>6)&0x3F), byte(0x80|cp&0x3F))
	}
	return utf8.AppendRune(s, cp)
}

// parseString parses the JSON string starting at the opening quote.
func parseString() string {
	s := []byte{}
	pos++
	for in[pos] != '"' {
		c := in[pos]
		pos++
		if c != '\\' {
			s = append(s, c)
			continue
		}
		e := in[pos]
		pos++
		switch e {
		case 'n':
			s = append(s, '\n')
		case 't':
			s = append(s, '\t')
		case 'r':
			s = append(s, '\r')
		case 'b':
			s = append(s, '\b')
		case 'f':
			s = append(s, '\f')
		case 'u':
			cp := hex4(pos)
			pos += 4
			if cp >= 0xD800 && cp < 0xDC00 && in[pos] == '\\' && in[pos+1] == 'u' {
				if lo := hex4(pos + 2); lo >= 0xDC00 && lo < 0xE000 {
					cp = 0x10000 + (cp-0xD800)<<10 + (lo - 0xDC00)
					pos += 6
				}
			}
			s = appendCode(s, cp)
		default:
			s = append(s, e)
		}
	}
	pos++
	return string(s)
}

func isWs(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f'
}

func main() {
	in, _ = io.ReadAll(os.Stdin)
	holdings := map[string]int64{}
	var gain int64
	var out []int64
	for pos < len(in) && in[pos] != '[' {
		pos++
	}
	pos++
	for {
		for pos < len(in) && in[pos] != '"' && in[pos] != ']' {
			pos++
		}
		if pos >= len(in) || in[pos] == ']' {
			break
		}
		line := parseString()
		var p []string
		for i := 0; i < len(line); {
			for i < len(line) && isWs(line[i]) {
				i++
			}
			j := i
			for j < len(line) && !isWs(line[j]) {
				j++
			}
			if j > i {
				p = append(p, line[i:j])
			}
			i = j
		}
		if p[0] == "QUERY" {
			out = append(out, gain)
			continue
		}
		v, _ := strconv.ParseInt(p[2], 10, 64)
		if p[0] == "CHANGE" {
			gain += holdings[p[1]] * v
		} else if p[0] == "BUY" {
			holdings[p[1]] += v
		} else {
			holdings[p[1]] -= v
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	buf := strconv.AppendInt(nil, int64(len(out)), 10)
	buf = append(buf, '\n')
	for _, g := range out {
		buf = strconv.AppendInt(buf, g, 10)
		buf = append(buf, '\n')
	}
	w.Write(buf)
}
